import { progressModel } from './progress-model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const km=v=>new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}).format(v/1000);
const time=v=>{const n=Math.round(v);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');};
const date=v=>new Date(v+'T12:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:'UTC'});
const month=v=>new Date(v+'-01T12:00Z').toLocaleDateString('en-AU',{month:'long',year:'numeric',timeZone:'UTC'});
const distance=v=>v===1609.344?'1 mile':v===3218.688?'2 miles':v<1000?v+' m':km(v)+' km';
const detail=s=>'/app.html?activity='+encodeURIComponent(s.id);
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';

export function mountProgress(root,data){
 let sport='run',model=progressModel(data.sessions,data.anchor,sport),selected=model.monthly.at(-1).key,metric='distanceM',day=null,benchmark=1000;
 function render(){
  model=progressModel(data.sessions,data.anchor,sport);
  const active=model.monthly.find(m=>m.key===selected)||model.monthly.at(-1);selected=active.key;
  const index=model.monthly.indexOf(active),previous=model.monthly[index-1];
  // Compare only the immediately preceding calendar month, not the last month
  // containing imports. An empty month is missing evidence, not a recovery week.
  const previousKey=new Date(Date.UTC(Number(selected.slice(0,4)),Number(selected.slice(5))-2,1)).toISOString().slice(0,7);
  const compare=previous?.key===previousKey?previous:null;
  const chosen=active.daily.find(d=>d.date===day)||active.daily[Math.min(active.through,active.days)-1];day=chosen.date;
  const max=Math.max(1,...active.daily.slice(0,active.through).map(d=>d[metric]),...(compare?.daily.map(d=>d[metric])||[]));
  const unit=metric==='distanceM'?'km':'min',value=v=>metric==='distanceM'?km(v):Math.round(v/60).toString();
  const width=innerWidth<=600?400:600,left=45,right=width-20,top=18,bottom=215,x=d=>left+(d-1)/30*(right-left),y=v=>bottom-v/max*(bottom-top);
  // Daily cumulative totals are a staircase: a curve would invent distance
  // between training days. Rounded joins soften the geometry without distortion.
  const path=rows=>rows.map((d,i)=>`${i?'H'+x(d.day).toFixed(2)+'V':'M'+x(d.day).toFixed(2)+','}${y(d[metric]).toFixed(2)}`).join(' ');
  const currentRows=active.daily.slice(0,active.through),trace=path(currentRows),comparison=compare?path(compare.daily):'';
  const selectedMetric=chosen[metric],baseline=compare?.daily[Math.min(chosen.day,compare.days)-1]?.[metric];
  const offset=(new Date(selected+'-01T12:00Z').getUTCDay()+6)%7;
  const effort=model.efforts.find(e=>e.distanceM===benchmark),available=model.efforts.filter(e=>e.results.length);
  const fastest=available.map(e=>({distance:e.distanceM,...e.results[0]}));
  const pMin=fastest.length?Math.min(...fastest.map(e=>e.paceSPerKm))-20:0,pMax=fastest.length?Math.max(...fastest.map(e=>e.paceSPerKm))+20:1;
  const px=d=>50+(Math.log(d)-Math.log(400))/(Math.log(Math.max(5000,...fastest.map(e=>e.distance)))-Math.log(400))*(width-100),py=p=>28+(p-pMin)/(pMax-pMin)*120;
  root.innerHTML=`<div class="pr-heading"><div><h2>See your training build.</h2><p>Distance, consistency and your fastest recorded efforts.</p></div><div class="tr-window" role="group" aria-label="Progress sport">${[['run','Running'],['walk','Walking'],['all','All activities']].map(([key,label])=>`<button data-progress-sport="${key}" aria-pressed="${sport===key}">${label}</button>`).join('')}</div></div>
  <div class="pr-workspace"><section class="pr-month" aria-labelledby="pr-month-title"><div class="pr-panel-head"><h3 id="pr-month-title">The month in motion.</h3><label class="pr-month-select"><span class="sr-only">Progress month</span><select id="progress-month">${model.monthly.toReversed().map(m=>`<option value="${m.key}" ${selected===m.key?'selected':''}>${month(m.key)}</option>`).join('')}</select></label></div>
  <div class="pr-readout"><div><strong id="pr-value">${value(selectedMetric)}</strong><span id="pr-unit">${unit}</span></div><p id="pr-context">Through ${date(chosen.date)}${baseline!==undefined?' · '+value(baseline)+' '+unit+' in '+month(compare.key).split(' ')[0]+' by day '+Math.min(chosen.day,compare.days):''}</p></div>
  <div class="pr-controls" role="group" aria-label="Monthly measurement"><button data-progress-metric="distanceM" aria-pressed="${metric==='distanceM'}">Distance</button><button data-progress-metric="durationS" aria-pressed="${metric==='durationS'}">Recorded time</button></div>
  <svg class="pr-cumulative" viewBox="0 0 ${width} 260" role="img" aria-labelledby="pr-chart-title pr-chart-desc"><title id="pr-chart-title">Cumulative ${metric==='distanceM'?'distance':'recorded time'} for ${month(selected)}</title><desc id="pr-chart-desc">${value(currentRows.at(-1)[metric])} ${unit} from imported ${sport==='all'?'activities':sport==='run'?'runs':'walks'}. ${compare?'Dashed line: '+month(compare.key)+'.':'No preceding month available for comparison.'} Use the calendar or daily values below to inspect exact values.</desc><defs><linearGradient id="pr-area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--color-accent)" stop-opacity=".15"/><stop offset="1" stop-color="var(--color-accent)" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(f=>`<path class="pr-grid" d="M${left} ${y(max*f)}H${right}"/><text x="2" y="${y(max*f)+4}">${value(max*f)}</text>`).join('')}${comparison?`<path class="pr-comparison" d="${comparison}"/>`:''}<path class="pr-area" d="${trace} V${bottom}H${left}Z"/><path class="pr-line" d="${trace}"/><g id="pr-cursor"><path d="M${x(chosen.day)} ${top}V${bottom}"/><circle cx="${x(chosen.day)}" cy="${y(selectedMetric)}" r="5"/></g>${[1,8,15,22,active.days].map(d=>`<text x="${x(d)}" y="246" text-anchor="middle">${d}</text>`).join('')}</svg>
  <div class="pr-legend"><span><i></i>${month(selected)}</span>${compare?`<span><i class="pr-dashed"></i>${month(compare.key)}</span>`:''}</div><p class="pr-note">Imported history only. ${metric==='durationS'?'Timer, running and moving time retain their source basis. ':''}Steps mark recorded days; missing imports stay unknown. ${active.key===data.anchor.slice(0,7)?'Current month stops today.':''}</p>
  <details class="pr-values"><summary>Daily values and calculation</summary><p>Calendar-day cumulative totals, summed from canonical activities in the selected history window. ${data.window==='90'?'The earliest month may be partial because this view covers 90 days.':''} No smoothing or fitness inference.</p><div class="pr-table-scroll"><table><caption>Daily cumulative totals for ${month(selected)}</caption><thead><tr><th scope="col">Date</th><th scope="col">Distance</th><th scope="col">Recorded time</th></tr></thead><tbody>${currentRows.map(d=>`<tr><th scope="row">${date(d.date)}</th><td>${km(d.distanceM)} km</td><td>${time(d.durationS)}</td></tr>`).join('')}</tbody></table></div></details></section>
  <section class="pr-calendar-panel" aria-labelledby="pr-calendar-title"><div class="pr-panel-head"><h3 id="pr-calendar-title">Your training days.</h3><span>${active.activeDays} days · ${active.count} sessions</span></div><p class="pr-note">Select a date to inspect its sessions.</p><div class="pr-weekdays" aria-hidden="true">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="pr-calendar" role="group" aria-label="Training dates for ${month(selected)}" aria-describedby="pr-calendar-help">${Array.from({length:offset},()=>'<span></span>').join('')}${active.daily.map(d=>`<button data-progress-day="${d.date}" tabindex="${chosen.date===d.date?0:-1}" aria-pressed="${chosen.date===d.date}" aria-label="${date(d.date)}, ${d.sessionIds.length} imported sessions, ${km(d.sessions.reduce((n,s)=>n+(s.distanceM??0),0))} kilometres" ${d.day>active.through?'disabled':''} class="${d.sessions.length?'has-session':''}"><span>${d.day}</span><i aria-hidden="true">${d.sessions.length>1?d.sessions.length:d.sessions.length?'•':''}</i></button>`).join('')}</div>
  <p id="pr-calendar-help" class="sr-only">Arrow keys move one day or week. Home selects the first day; End selects the last available day.</p><div id="pr-day-sessions" class="pr-day-sessions" aria-live="polite"><h4>${date(chosen.date)}</h4>${chosen.sessions.length?chosen.sessions.map(s=>`<a href="${detail(s)}"><span><strong>${esc(s.title)}</strong><small>${esc(s.source)} · ${esc(s.durationBasis)} time</small></span><span>${s.distanceM===null?'—':km(s.distanceM)+' km'}<small>${s.durationS===null?'—':time(s.durationS)}</small></span>${arrow}</a>`).join(''):'<p>No imported session on this date.</p>'}</div></section></div>
  ${sport!=='walk'?`<section class="pr-efforts" aria-labelledby="pr-effort-title"><div class="pr-panel-head"><div><h3 id="pr-effort-title">Your best recorded efforts.</h3><p class="pr-note">Fastest elapsed-time windows inside GPS runs. Estimated between recorded samples.</p></div><span>${model.sessions.filter(s=>s.bestEfforts?.length).length} eligible GPS ${model.sessions.filter(s=>s.bestEfforts?.length).length===1?'run':'runs'}</span></div>${fastest.length?`<div class="pr-effort-layout"><div><svg viewBox="0 0 ${width} 195" class="pr-effort-curve" role="img" aria-label="Fastest recorded pace by benchmark distance. Faster pace is higher. Only benchmarks supported by GPS samples appear.">${[pMin,(pMin+pMax)/2,pMax].map(v=>`<path class="pr-grid" d="M45 ${py(v)}H${width-35}"/><text x="0" y="${py(v)+4}">${time(v)}</text>`).join('')}<path class="pr-effort-line" d="${fastest.map((e,i)=>`${i?'L':'M'}${px(e.distance)},${py(e.paceSPerKm)}`).join(' ')}"/>${fastest.map(e=>`<circle cx="${px(e.distance)}" cy="${py(e.paceSPerKm)}" r="5"/>${[400,1000,5000,fastest.at(-1).distance].includes(e.distance)?`<text x="${px(e.distance)}" y="183" text-anchor="middle">${distance(e.distance)}</text>`:''}`).join('')}</svg><p class="pr-note">Pace /km · logarithmic distance axis · connecting lines are guides. These are records within imported history, not lifetime or race-certified PRs.</p></div><div><label class="pr-benchmark">Benchmark distance<select id="progress-benchmark">${model.efforts.map(e=>`<option value="${e.distanceM}" ${benchmark===e.distanceM?'selected':''}>${distance(e.distanceM)}${!e.results.length?' · no eligible data':''}</option>`).join('')}</select></label><ol class="pr-ranking">${effort?.results.length?effort.results.slice(0,3).map(e=>`<li><a href="${detail(e)}"><span><strong>${time(e.elapsedS)}</strong><small>${time(e.paceSPerKm)} /km · ${date(e.date)}</small></span><span>${esc(e.title)}</span>${arrow}</a></li>`).join(''):'<li>No eligible GPS recording covers this distance yet.</li>'}</ol></div></div>`:'<div class="pr-empty"><h4>A GPS run unlocks the curve.</h4><p>Summary screenshots preserve your totals and splits. Best-effort windows need timestamped distance and GPS samples; we never recreate them from an image.</p><a href="/account">Import a recording</a></div>'}<details class="pr-values"><summary>How best efforts are calculated</summary><p>Searches both start- and end-aligned sample boundaries, interpolating elapsed time at exact benchmark distances. Includes stationary time within each window. Missing positions, distance resets, non-increasing timestamps, gaps over 15 seconds and speeds above 12 m/s split the usable recording. One best effort per activity and distance. This conservative method can omit legitimate efforts around recording gaps.</p></details></section>`:''}`;
  root.querySelectorAll('[data-progress-sport]').forEach(b=>b.addEventListener('click',()=>{sport=b.dataset.progressSport;day=null;render();root.querySelector(`[data-progress-sport="${sport}"]`).focus({preventScroll:true});}));
  root.querySelector('#progress-month').addEventListener('change',e=>{selected=e.target.value;day=null;render();root.querySelector('#progress-month').focus({preventScroll:true});});
  root.querySelectorAll('[data-progress-metric]').forEach(b=>b.addEventListener('click',()=>{metric=b.dataset.progressMetric;render();root.querySelector(`[data-progress-metric="${metric}"]`).focus({preventScroll:true});}));
  root.querySelectorAll('[data-progress-day]').forEach(b=>b.addEventListener('click',()=>{day=b.dataset.progressDay;render();root.querySelector(`[data-progress-day="${day}"]`).focus({preventScroll:true});}));
  root.querySelector('.pr-calendar').addEventListener('keydown',e=>{const n=Number(day.slice(8)),next={ArrowLeft:n-1,ArrowRight:n+1,ArrowUp:n-7,ArrowDown:n+7,Home:1,End:active.through}[e.key];if(next!==undefined){e.preventDefault();day=active.daily[Math.max(0,Math.min(active.through-1,next-1))].date;render();root.querySelector(`[data-progress-day="${day}"]`).focus({preventScroll:true});}});
  root.querySelector('#progress-benchmark')?.addEventListener('change',e=>{benchmark=Number(e.target.value);render();root.querySelector('#progress-benchmark').focus({preventScroll:true});});
 }
 const breakpoint=matchMedia('(max-width:600px)');const adapt=()=>{if(root.isConnected)render();else breakpoint.removeEventListener('change',adapt);};breakpoint.addEventListener('change',adapt);
 render();
}
